// InsertRecordsRequest Request to insert ProximaRecords
//
// ## Example JSON
//
// ```json
//
//	{
//	    "records": [
//	        {
//	            "id": "doc_1",
//	            "vector": [0.1, 0.2, 0.3],
//	            "props": {
//	                "category": "electronics",
//	                "price": 299.99,
//	                "in_stock": true
//	            },
//	            "text_fields": [
//	                {
//	                    "name": "description",
//	                    "content": "A detailed product description...",
//	                    "storage_hint": "adaptive"
//	                }
//	            ],
//	            "source": "catalog_import"
//	        }
//	    ],
//	    "validate_schema": true
//	}
//
// ```
// Not supported in v0.2: optimistic versioning, conditional-write predicates,
// update-by-filter, delete-by-filter, and patch / partial-record update. The
// live contract is exposed via `WriteContractHealth` on the route-health
// diagnostic endpoint (`GET /api/v2/_diagnostics/collections/{id}/route-health`);
// see also `docs/SUPPORTED_SURFACE.adoc` "Not Supported in v0.2".
type InsertRecordsRequest struct {
	// Records Records to insert
	Records []ProximaRecordInput `json:"records"`

	// Upsert Whether existing records with the same ID should be replaced.
	//
	// The current durable record write path is idempotent/upsert-oriented; this
	// field is accepted so SDKs can expose explicit upsert intent without
	// leaving the OpenAPI contract.
	Upsert *bool `json:"upsert,omitempty"`

	// ValidateSchema Whether to validate against collection schema (default: true)
	ValidateSchema *bool `json:"validate_schema,omitempty"`
}

// InsertRecordsResponse Response for insert operation
type InsertRecordsResponse struct {
	// Errors Detailed errors for failed records
	Errors []InsertError `json:"errors"`

	// FailedCount Number of failed records
	FailedCount int `json:"failed_count"`

	// InsertedCount Number of successfully inserted records
	InsertedCount int `json:"inserted_count"`

	// InsertedIds IDs of successfully inserted records
	InsertedIds []string `json:"inserted_ids"`
}

