// RestColumnDefinition Column definition for schema
type RestColumnDefinition struct {
	// DataType Data type
	//
	// Supported types:
	// - "text": Variable-length UTF-8 text
	// - "text_large": Large text with sidecar storage
	// - "integer": 64-bit signed integer
	// - "float": 64-bit floating point
	// - "decimal": 128-bit decimal (precision, scale)
	// - "boolean": True/false
	// - "timestamp": Microseconds since epoch
	// - "timestamp_tz": Timestamp with timezone
	// - "date": Days since epoch
	// - "time": Microseconds since midnight
	// - "uuid": RFC 4122 UUID
	// - "binary": Raw bytes
	// - "json": Validated JSON
	// - "array_text", "array_integer", "array_float", "array_boolean"
	// - "map_string_string", "map_string_any"
	// - "geo_point": Latitude/longitude point
	// - "vector": Fixed-dimension vector (specify dimension)
	DataType string `json:"data_type"`

	// Filterable Enable filtering on this column
	//
	// When true, the column can be used in WHERE clauses.
	// Default: true for indexed columns, false otherwise
	Filterable *bool `json:"filterable,omitempty"`

	// Indexed Create secondary index for this column
	//
	// Improves query performance for equality/range filters.
	// Default: false
	Indexed *bool `json:"indexed,omitempty"`

	// MaxLength Maximum length for TEXT/BINARY columns
	//
	// Default: no limit
	MaxLength *int32 `json:"max_length,omitempty"`

	// Name Column name
	Name string `json:"name"`

	// Nullable Whether null values are allowed
	//
	// Default: true
	Nullable *bool `json:"nullable,omitempty"`

	// Precision Precision for DECIMAL type (1-38)
	Precision *int32 `json:"precision,omitempty"`

	// Scale Scale for DECIMAL type (0-precision)
	Scale *int32 `json:"scale,omitempty"`

	// VectorDimension Dimension for VECTOR type
	VectorDimension *int32 `json:"vector_dimension,omitempty"`
}

// ScanRecordsRequest Body of `POST /records/scan`. Mirrors the OpenAPI `ScanRecordsRequest`
// schema; all fields optional so an empty `{}` returns the first page.
type ScanRecordsRequest struct {
	// Cursor Opaque continuation token returned as `next_cursor` from a
	// prior page. Omit / null to start from the beginning.
	Cursor *string `json:"cursor,omitempty"`

	// Filter Metadata filter applied (before the limit) to the scanned page.
	// Accepts either the typed list form `[{field,op,value}]` (mirrors
	// `searchRecords.filters`) or a simple equality map `{field: value}`.
	Filter        interface{} `json:"filter,omitempty"`
	IncludeText   *bool       `json:"include_text,omitempty"`
	IncludeVector *bool       `json:"include_vector,omitempty"`

	// Limit Max records to return in this page. Server enforces upper bound.
	Limit *int32 `json:"limit,omitempty"`
}

// ScanRecordsResponse Response shape for `scanRecords`. Empty `records` + null
// `next_cursor` signals end-of-scan. Each record matches the OpenAPI
// `RecordResponse` schema (same shape used by `getRecord`).
type ScanRecordsResponse struct {
	ContentRevision      int64              `json:"content_revision"`
	ContentRevisionToken string             `json:"content_revision_token"`
	NextCursor           *string            `json:"next_cursor,omitempty"`
	Records              []RecordV2Response `json:"records"`
	ScannedCount         *int64             `json:"scanned_count,omitempty"`
}

