// TextFieldInput Input format for TEXT fields
//
// TEXT fields are stored in dedicated columns with optional chunking
// for large content. The storage hint helps optimize storage strategy.
type TextFieldInput struct {
	// Content Text content
	Content string `json:"content"`

	// Name Field name
	Name string `json:"name"`

	// StorageHint Storage strategy hint
	//
	// - "inline": Store inline in main column (<4KB)
	// - "chunked": Split into chunks with embeddings (4KB-1MB)
	// - "sidecar": Store in separate sidecar file (>1MB)
	// - "adaptive": Auto-select based on content size (default)
	StorageHint *string `json:"storage_hint,omitempty"`
}

// TextFieldOutput Output format for TEXT fields
type TextFieldOutput struct {
	// ChunkCount Number of chunks (for chunked storage)
	ChunkCount *int32 `json:"chunk_count,omitempty"`

	// Content Text content (may be truncated for large content)
	Content string `json:"content"`

	// Name Field name
	Name string `json:"name"`

	// Truncated Whether content was truncated
	Truncated bool `json:"truncated"`
}

