// TypedFilter A typed filter for search operations
//
// Supports various comparison operators with type-safe values.
type TypedFilter struct {
	// Field Field name to filter on
	Field string `json:"field"`

	// Op Comparison operator
	//
	// Supported operators:
	// - "eq": Equals
	// - "neq": Not equals
	// - "gt": Greater than
	// - "gte": Greater than or equal
	// - "lt": Less than
	// - "lte": Less than or equal
	// - "contains": String/array contains
	// - "between": Value is between two bounds (requires value_upper)
	// - "in": Value is in a list
	// - "starts_with": String starts with prefix
	// - "ends_with": String ends with suffix
	Op string `json:"op"`

	// Value Filter value (type depends on field type)
	Value interface{} `json:"value"`

	// ValueUpper Upper bound for "between" operator
	ValueUpper interface{} `json:"value_upper,omitempty"`
}

// TypedSearchRequest Search request with typed filters
//
// ## Example JSON
//
// ```json
//
//	{
//	    "vector": [0.1, 0.2, 0.3],
//	    "top_k": 10,
//	    "filters": [
//	        {"field": "category", "op": "eq", "value": "electronics"},
//	        {"field": "price", "op": "lt", "value": 500},
//	        {"field": "in_stock", "op": "eq", "value": true}
//	    ],
//	    "include_text": true
//	}
//
// ```
type TypedSearchRequest struct {
	// Debug Return the SearchPlanTrace + a human-readable route explain
	// in the response (LLD §1 contract). Defaults to `false` so
	// non-debug requests don't pay the JSON serialization cost of
	// the ~30-field trace envelope.
	Debug *bool `json:"debug,omitempty"`

	// Filters Typed filters with operator support
	Filters *[]TypedFilter `json:"filters,omitempty"`

	// IncludeText Whether to include TEXT fields in results (default: false)
	//
	// TEXT fields can be large, so they are excluded by default.
	// Set to true to include them in the response.
	IncludeText *bool `json:"include_text,omitempty"`

	// IncludeVector Whether to include the vector in results (default: false)
	//
	// Vector data can be large, so it is excluded by default.
	IncludeVector *bool `json:"include_vector,omitempty"`

	// TopK Number of results to return
	TopK int `json:"top_k"`

	// Vector Query vector
	Vector []float32 `json:"vector"`
}

// TypedSearchResponse Search response with typed results
type TypedSearchResponse struct {
	// Explain Human-readable explain summary derived from the SearchPlanTrace.
	// Only emitted when the request sets `debug=true` — gives an on-call
	// operator a one-glance view of the plan, cache result, and any
	// actionable hints (high scan fraction, repair triggered, ...).
	Explain interface{} `json:"explain,omitempty"`

	// LatencyMs Search latency in milliseconds
	LatencyMs int64 `json:"latency_ms"`

	// PredicateShortfall TD-064: predicate-aware recall shortfall (REST wire shape).
	//
	// Mirrors `observability::search_plan_trace::PredicateShortfall` as an
	// explicit REST/OpenAPI schema so the field is typed and documented on the
	// wire without forcing the observability type (or the slim `IndexQueryResult`
	// DTO) to derive `ToSchema`.
	PredicateShortfall *PredicateShortfallWire `json:"predicate_shortfall,omitempty"`

	// RequestId Request ID for tracing
	RequestId string `json:"request_id"`

	// Results Search results
	Results []TypedSearchResult `json:"results"`

	// SearchPlanTrace SearchPlanTrace (LLD §10) — the per-query telemetry envelope that
	// upstream gateways consume for metering and planner-v2 training.
	// Phase 0 emits a stub trace populated from request_id + latency; later
	// phases fill in the per-stage counters. Only emitted when the request
	// sets `debug=true` (LLD §1 contract).
	SearchPlanTrace interface{} `json:"search_plan_trace,omitempty"`

	// TotalMatches Total number of matching documents (before top_k limit)
	TotalMatches *int64 `json:"total_matches,omitempty"`
}

// TypedSearchResult Search result with typed fields
type TypedSearchResult struct {
	// Id Record ID
	Id string `json:"id"`

	// Props Rich properties from the record
	Props map[string]interface{} `json:"props"`

	// Score Similarity score (0.0 - 1.0 for cosine, distance for L2)
	Score float32 `json:"score"`

	// TextFields TEXT fields (if include_text is true)
	TextFields *[]TextFieldOutput `json:"text_fields,omitempty"`

	// Vector Vector embedding (if requested)
	Vector *[]float32 `json:"vector,omitempty"`
}

